import test from 'node:test';
import assert from 'node:assert/strict';
import {EXPERT_LEVELS,EXPERT_CHAPTERS} from '../src/expert-levels.js';
import {validateLevels} from '../src/levels.js';
import {verifyPuzzleSolution} from '../src/puzzle-solver.js';
import {trace,movable} from '../src/optics.js';

/**
 * The expert campaign is generated by scripts/generate-expert-levels.mjs.
 * These assertions deliberately use the same validator and optics engine as
 * gameplay, so a level can never ship unless its authored solution is playable.
 */
const levels=validateLevels(EXPERT_LEVELS);

test('expert campaign exposes 50 levels in five chapters',()=>{
 assert.equal(levels.length,50);
 assert.equal(EXPERT_CHAPTERS.length,5);
 const perChapter=new Map();
 for(const level of levels){
  assert.ok(level.chapter&&typeof level.chapter.pl==='string'&&typeof level.chapter.en==='string');
  assert.ok(level.chapter.pl.length>3&&level.chapter.en.length>3);
  perChapter.set(level.chapter.pl,(perChapter.get(level.chapter.pl)||0)+1);
 }
 assert.deepEqual([...perChapter.values()],[10,10,10,10,10]);
 assert.equal(new Set(levels.map(l=>l.title.pl)).size,50,'Polish titles are unique');
 assert.equal(new Set(levels.map(l=>l.title.en)).size,50,'English titles are unique');
 for(const level of levels){
  assert.ok(level.description.pl.length>20&&level.description.en.length>20);
  assert.ok(level.difficulty>=1&&level.difficulty<=5);
  const chapterNumber=Number(level.chapter.pl.match(/0(\d)/)?.[1]);
  assert.equal(level.difficulty,chapterNumber,'difficulty matches the campaign tier');
  assert.equal(level.startMovablesInTray,true);
  assert.ok(level.mechanics.length>0);
 }
});

test('every expert level carries three useful bilingual hints',()=>{
 for(const [index,level] of levels.entries()){
  assert.equal(level.hints.length,3,'level '+(index+1));
  for(const [tier,hint] of level.hints.entries()){
   assert.ok(hint.pl.length>=20,'level '+(index+1)+' hint '+(tier+1)+' PL');
   assert.ok(hint.en.length>=20,'level '+(index+1)+' hint '+(tier+1)+' EN');
   assert.ok(!/\{[a-z]+\}/i.test(hint.pl+hint.en),'no raw template tokens');
  }
  assert.notEqual(level.hints[0].pl,level.hints[1].pl,'hints escalate');
  // The concrete tier must point at the real first move of the verified route.
  const first=level.solution[0];
  const piece=level.pieces[first.index];
  const cell='('+piece[1]+', '+piece[2]+')';
  assert.ok(level.hints[2].pl.includes(cell),'level '+(index+1)+' hint 3 names the first move cell');
  assert.ok(level.hints[2].en.includes(cell),'level '+(index+1)+' hint 3 EN names the first move cell');
 }
});

test('every expert solution is accepted by the live puzzle engine',()=>{
 for(const [index,level] of levels.entries()){
  const movableIndexes=level.pieces.map(([type],id)=>movable.has(type)?id:-1).filter(id=>id>=0);
  assert.equal(level.solution.length,movableIndexes.length,'level '+(index+1)+': all optics are used');
  assert.equal(new Set(level.solution.map(step=>step.index)).size,level.solution.length);
  const fixedCells=new Set(level.pieces.filter(([type])=>!movable.has(type)).map(([,x,y])=>x+','+y));
  const solutionCells=new Set();
  for(const step of level.solution){
   const key=step.x+','+step.y;
   assert.ok(!fixedCells.has(key),'level '+(index+1)+': optic may not land on scenery');
   assert.ok(!solutionCells.has(key),'level '+(index+1)+': two optics may not share a cell');
   solutionCells.add(key);
  }
  const verdict=verifyPuzzleSolution(level,level.solution);
  assert.equal(verdict.valid,true,'level '+(index+1)+': '+verdict.reason);
  assert.equal(verdict.result.won,true,'level '+(index+1)+': target reaches the exact colour');
  assert.equal(verdict.result.truncated,false);
  assert.deepEqual(verdict.result.unsupported,[]);
  // A level must require work: the untouched board cannot already win.
  const initial=trace(level.pieces.map(([type,x,y,rot,color],id)=>({id,type,x,y,rot,color,inTray:movable.has(type)})));
  assert.equal(initial.won,false,'level '+(index+1)+' must not start solved');
 }
});

test('expert campaign is mechanically and chromatically diverse',()=>{
 const used=new Set(),pieceTypes=new Set(),targetColors=new Set(),laserColors=new Set(),layouts=new Set();
 let wallLevels=0;
 for(const level of levels){
  for(const [type,,, ,color] of level.pieces){
   pieceTypes.add(type);
   if(movable.has(type))used.add(type);
   if(type==='target')targetColors.add(color);
   if(type==='laser')laserColors.add(color);
   if(type==='wall')wallLevels++;
  }
  layouts.add(JSON.stringify(level.pieces));
  for(const mechanic of level.mechanics)assert.ok(pieceTypes.has(mechanic),'metadata matches a real piece');
 }
 assert.equal(layouts.size,50,'no duplicated layouts');
 assert.ok(wallLevels>0);
 for(const required of ['mirror','bender','splitter','prism','doppler','filter','tangler'])
  assert.ok(used.has(required),'campaign uses '+required);
 for(const scenery of ['teleporter','conduit'])
  assert.ok(pieceTypes.has(scenery),'campaign uses '+scenery);
 assert.ok(targetColors.size>=4,'targets cover several wavelengths');
 assert.ok(laserColors.size>=3,'emitters cover several wavelengths');
 const chapterDifficulties=EXPERT_CHAPTERS.map(ch=>{
  const inChapter=levels.filter(l=>l.chapter.pl.includes(ch.pl));
  return inChapter.reduce((sum,l)=>sum+l.difficulty,0)/inChapter.length;
 });
 for(let i=1;i<chapterDifficulties.length;i++)
  assert.ok(chapterDifficulties[i]>=chapterDifficulties[i-1],'chapters do not get easier');
 assert.ok(chapterDifficulties[4]>chapterDifficulties[0],'the final tier is above the opening tier');
});
